(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const iso = d => d instanceof Date ? d.toISOString().slice(0,10) : String(d);
  const m = d3.rollups(rows.filter(r => iso(r.date).startsWith("2025")), v => d3.sum(v, r => r.revenue), r => iso(r.date).slice(5,7))
    .sort((a,b) => d3.ascending(a[0], b[0]))
    .map(([k, v]) => ({month: new Date(2025, +k-1, 1), revenue: v}));
  return Plot.plot({
    width: 800, height: 420, marginLeft: 70,
    title: "Monthly revenue, 2025",
    x: {type: "band", tickFormat: d => d3.timeFormat("%b")(d), label: null},
    y: {label: "Revenue ($)", grid: true, tickFormat: "s"},
    marks: [Plot.barY(m, {x: "month", y: "revenue"}), Plot.ruleY([0])]
  });
})()

